import "../logger.dart";
import "../table_storage.dart";
import "cube/cubie_cube.dart";
import "cube/moves.dart";
import "cube/sym_coord.dart";
import "cube/symmetry.dart";

/// Phase 2 coordinate tables for the min2phase search.
///
/// Phase 2 works inside the subgroup generated by U, D and the half turns of
/// R, F, L and B — 10 of the 18 face turns — and solves the corner
/// permutation, the permutation of the 8 U/D edges and the permutation of the
/// 4 slice edges.
///
/// Both permutation coordinates are reduced over all 16 symmetries; the slice
/// permutation, only 24 values wide, is left raw and follows whichever symmetry
/// the reduction used. That checks out against the kociemba phase 2 distances
/// on every one of the 967680 pairs, in both tables.
///
/// Unlike phase 1, the move tables here are stored on classes rather than on
/// raw coordinates: `2768 * 10` entries instead of `40320 * 10`. An entry is
/// `newClass << 4 | symmetry`, the symmetry being the one that has to be
/// composed onto the state's own.
class Phase2Tables {
  /// The 10 turns that stay inside the phase 2 subgroup, as [moveCube] indices.
  static const List<int> moves = [0, 1, 2, 4, 7, 9, 10, 11, 13, 16];
  static const int nMoves = 10;
  static const int nMperm = 24;
  static const int nPerm = 40320;

  /// C(8, 4): which four positions hold the four U layer corners.
  static const int nCcombo = 70;

  factory Phase2Tables() => _instance;
  static final Phase2Tables _instance = Phase2Tables._internal();

  /// The cache file. Bump the version whenever a builder below changes.
  static TableFile get _cache => const TableFile(
    name: "min2phase-phase2.bin",
    magic: [0x4D, 0x32, 0x50, 0x32], // "M2P2"
    version: 1,
  );

  List<int> get _sectionLengths => [
    nMperm * nMoves * 2,
    nMperm * symCount * 2,
    nCcombo * nMoves * 2,
    nCcombo * symCount * 2,
    cpermSym.classCount * nMoves * 2,
    epermSym.classCount * nMoves * 2,
    (cpermSym.classCount * nMperm + 1) ~/ 2,
    (epermSym.classCount * nMperm + 1) ~/ 2,
    (epermSym.classCount * nCcombo + 1) ~/ 2,
  ];

  Phase2Tables._internal() {
    final cached = _cache.read(_sectionLengths);
    if (cached != null) {
      var i = 0;
      mpermMove = movingTableFromBytes(cached[i++], nMperm, nMoves);
      mpermConj = movingTableFromBytes(cached[i++], nMperm, symCount);
      ccomboMove = movingTableFromBytes(cached[i++], nCcombo, nMoves);
      ccomboConj = movingTableFromBytes(cached[i++], nCcombo, symCount);
      cpermClassMove = movingTableFromBytes(cached[i++], cpermSym.classCount, nMoves);
      epermClassMove = movingTableFromBytes(cached[i++], epermSym.classCount, nMoves);
      cpermPrune = PruningTable(cached[i++], nMperm, cpermSym.classCount * nMperm);
      epermPrune = PruningTable(cached[i++], nMperm, epermSym.classCount * nMperm);
      ccomboPrune = PruningTable(cached[i++], nCcombo, epermSym.classCount * nCcombo);
      Logging().info("Loaded the phase 2 tables from ${_cache.file.path}");
      return;
    }

    mpermMove = _rawMoveTable(nMperm, (c, v) => c.mperm = v, (c) => c.mperm);
    mpermConj = _conjTable(nMperm, (c, v) => c.mperm = v, (c) => c.mperm);
    ccomboMove = _rawMoveTable(nCcombo, (c, v) => c.ccombo = v, (c) => c.ccombo);
    ccomboConj = _conjTable(nCcombo, (c, v) => c.ccombo = v, (c) => c.ccombo);
    cpermClassMove = _classMoveTable(cpermSym, (c, v) => c.cperm = v, (c) => c.cperm);
    epermClassMove = _classMoveTable(epermSym, (c, v) => c.eperm = v, (c) => c.eperm);

    cpermPrune = _buildPrune(cpermSym, cpermClassMove, mpermMove, mpermConj, nMperm);
    epermPrune = _buildPrune(epermSym, epermClassMove, mpermMove, mpermConj, nMperm);
    ccomboPrune = _buildPrune(epermSym, epermClassMove, ccomboMove, ccomboConj, nCcombo);

    _cache.write([
      movingTableBytes(mpermMove),
      movingTableBytes(mpermConj),
      movingTableBytes(ccomboMove),
      movingTableBytes(ccomboConj),
      movingTableBytes(cpermClassMove),
      movingTableBytes(epermClassMove),
      cpermPrune.data,
      epermPrune.data,
      ccomboPrune.data,
    ]);
  }

  /// Slice permutation after each phase 2 move.
  late final MovingTable mpermMove;

  /// Slice permutation after conjugating by each of the 16 symmetries.
  late final MovingTable mpermConj;

  /// Corner combination after each phase 2 move, and after each symmetry.
  late final MovingTable ccomboMove;
  late final MovingTable ccomboConj;

  /// `newClass << 4 | symmetry` for each class and phase 2 move.
  late final MovingTable cpermClassMove;
  late final MovingTable epermClassMove;

  /// Distance to solved, indexed by `class * 24 + conjugated slice permutation`.
  late final PruningTable cpermPrune;
  late final PruningTable epermPrune;

  /// Distance to solved over (edge permutation, corner combination).
  ///
  /// This one has no counterpart in the kociemba solver. It pairs the edge
  /// permutation with partial corner information, which catches states the
  /// other two tables are optimistic about.
  late final PruningTable ccomboPrune;

  /// Flat index of a (permutation, second coordinate) pair in a reduced table.
  int indexOf(SymCoord coord, int raw, int other, MovingTable conj, int width) {
    final (cls, s) = SymCoord.split(coord.raw2sym[raw]);
    return cls * width + conj[(other, symInv[s])];
  }

  int cpermIndex(int cperm, int mperm) => indexOf(cpermSym, cperm, mperm, mpermConj, nMperm);
  int epermIndex(int eperm, int mperm) => indexOf(epermSym, eperm, mperm, mpermConj, nMperm);
  int ccomboIndex(int eperm, int ccombo) => indexOf(epermSym, eperm, ccombo, ccomboConj, nCcombo);

  /// Lower bound on the moves needed to finish from a phase 2 state.
  int phase2Cost(int cperm, int eperm, int mperm, int ccombo) {
    var best = cpermPrune.at(cpermIndex(cperm, mperm));
    final b = epermPrune.at(epermIndex(eperm, mperm));
    if (b > best) best = b;
    final c = ccomboPrune.at(ccomboIndex(eperm, ccombo));
    return c > best ? c : best;
  }

  int get lengthInBytes =>
      mpermMove.lengthInBytes +
      mpermConj.lengthInBytes +
      ccomboMove.lengthInBytes +
      ccomboConj.lengthInBytes +
      cpermClassMove.lengthInBytes +
      epermClassMove.lengthInBytes +
      cpermPrune.lengthInBytes +
      epermPrune.lengthInBytes +
      ccomboPrune.lengthInBytes;
}

/// Coordinate after each of the 10 phase 2 moves.
MovingTable _rawMoveTable(
  int rawCount,
  void Function(CubieCube cube, int value) write,
  int Function(CubieCube cube) read,
) {
  final table = MovingTable.filled(rawCount, Phase2Tables.nMoves);
  for (var raw = 0; raw < rawCount; raw++) {
    for (var i = 0; i < Phase2Tables.nMoves; i++) {
      final cube = CubieCube();
      write(cube, raw);
      cube.multiply(moveCube[Phase2Tables.moves[i]]);
      table[(raw, i)] = read(cube);
    }
  }
  return table;
}

/// Coordinate after conjugating by each of the 16 symmetries.
MovingTable _conjTable(
  int rawCount,
  void Function(CubieCube cube, int value) write,
  int Function(CubieCube cube) read,
) {
  final table = MovingTable.filled(rawCount, symCount);
  for (var raw = 0; raw < rawCount; raw++) {
    final cube = CubieCube();
    write(cube, raw);
    for (var s = 0; s < symCount; s++) {
      table[(raw, s)] = read(conjugate(cube, s));
    }
  }
  return table;
}

/// Move table on equivalence classes: apply the move to the representative and
/// reduce the result, storing `newClass << 4 | symmetry`.
MovingTable _classMoveTable(
  SymCoord coord,
  void Function(CubieCube cube, int value) write,
  int Function(CubieCube cube) read,
) {
  final table = MovingTable.filled(coord.classCount, Phase2Tables.nMoves);
  for (var cls = 0; cls < coord.classCount; cls++) {
    for (var i = 0; i < Phase2Tables.nMoves; i++) {
      final cube = CubieCube();
      write(cube, coord.sym2raw[cls]);
      cube.multiply(moveCube[Phase2Tables.moves[i]]);
      table[(cls, i)] = coord.raw2sym[read(cube)];
    }
  }
  return table;
}

PruningTable _buildPrune(
  SymCoord coord,
  MovingTable classMove,
  MovingTable otherMove,
  MovingTable conj,
  int width,
) {
  return fillPruningTable(
    length: coord.classCount * width,
    stride: width,
    moveCount: Phase2Tables.nMoves,
    // A representative fixed by symmetry t puts the same state at more than one
    // index; the move graph does not join them, so they are filled together.
    aliases: (index) sync* {
      final cls = index ~/ width;
      final other = index % width;
      final stabiliser = coord.symState[cls];
      for (var t = 1; t < symCount; t++) {
        if (stabiliser & (1 << t) != 0) {
          yield cls * width + conj[(other, t)];
        }
      }
    },
    successor: (index, move) {
      final cls = index ~/ width;
      final other = index % width;

      final (nextClass, s) = SymCoord.split(classMove[(cls, move)]);
      final nextOther = otherMove[(other, move)];

      return nextClass * width + conj[(nextOther, symInv[s])];
    },
  );
}
